/*
 * @interlace/ui — the additive baseline every component needs.
 *
 *   @import "tailwindcss";
 *   @import "@interlace/ui/styles/base.css";
 *
 * This is what `interlace-base` installs, and every registry component
 * depends on it, so it lands in an adopter's app with their FIRST component.
 * It therefore adds and never replaces. `apps/registry/src/__tests__/
 * host-style-safety.test.ts` compiles a stock shadcn globals.css with and
 * without this file and holds that.
 *
 * ─── Four layers, each reading only the one before it ──────────────
 *
 *   1. brand/       raw `--interlace-*` values, one file per theme.
 *   2. semantics    the names components read (shadcn's + Interlace's),
 *                   bound to brand tokens, registered as Tailwind colours.
 *   3. structure/   type, layout, radius, motion. Brand-invariant.
 *   4. page/        opt-in page styling: fonts, preflight, fumadocs, shiki.
 *                   NOT imported here; index.css adds it.
 *
 * `packages/ui/__tests__/css-layer-lock.test.ts` enforces the direction.
 *
 * ─── Cascade layers ────────────────────────────────────────────────
 *
 * Tailwind declares `theme, base, components, utilities` first. Interlace
 * rules that style elements go INSIDE those layers (preflight in `base`,
 * prose and animation classes in `components`), so any utility at the call
 * site beats them. The three Interlace layers below rank above utilities,
 * which is safe only because they declare nothing but custom properties on
 * `:root`, `.dark`, `[data-scheme]` and `[data-theme]`:
 *
 *   interlace.bridge     fumadocs → shadcn aliases (page/fumadocs.css)
 *   interlace.brand      raw brand values. THE override surface: declare
 *                        `@layer interlace.brand { … }` after this import.
 *   interlace.semantics  aliases from semantic names to brand values.
 *
 * A host app's unlayered `:root { --primary: … }` beats all three.
 */

@layer interlace.bridge, interlace.brand, interlace.semantics;

/* 1. Brand. ORDER IS LOAD-BEARING: every theme file follows the default
 * (brand/interlace.css). `[data-theme='X']` and `.dark` tie at (0,1,0), so
 * theme X's light block must come after Interlace's dark block for
 * `[data-theme='X'].dark` to sit on a coherent stack. Adding a theme = one
 * file here + its row in THEMES (src/lib/theme-tokens.ts). */
@import "./brand/interlace.css";
@import "./brand/harbor.css";

/* 2. Semantics. */
@import "./semantics.css";

/* 3. Structure. */
@import "./structure/type.css";
@import "./structure/layout.css";
@import "./structure/radius.css";
@import "./structure/motion.css";
@import "./structure/scheme.css";

/*
 * @interlace/ui — "Harbor" theme (light + dark).
 *
 * The SECOND theme, and the reason Phase 8 is a multi-theme system rather
 * than a one-theme system claiming to be one. A contract nothing exercises
 * is a contract nobody has tested: until a palette that is not Interlace
 * resolved through the same cascade, "themes are supported" was an
 * assertion about code that had never run.
 *
 * ─── What this file is allowed to touch ───────────────────────────
 *
 * `--interlace-*` oklch literals, inside `@layer interlace.brand`, and
 * nothing else. No semantic alias (`--background`, `--primary`, `--viz-*`),
 * no `@theme` block, no component CSS. If a theme ever needs to reach past
 * the brand layer, the token graph is wrong — fix the graph, not the theme.
 *
 * ─── Selectors ────────────────────────────────────────────────────
 *
 *   [data-theme='harbor']                          harbor · light
 *   [data-theme='harbor'].dark                     harbor · dark
 *   [data-theme='harbor'][data-scheme='dark']      harbor · dark (attr form)
 *   [data-theme='harbor'] .dark                    harbor · dark (subtree)
 *   [data-theme='harbor'] [data-scheme='dark']     harbor · dark (subtree, attr)
 *
 * The two DESCENDANT forms are not decoration — without them a `.dark`
 * wrapper anywhere inside a Harbor page repaints that subtree in INTERLACE
 * dark, because the bare `.dark` block in brand/interlace.css re-declares
 * every brand literal on whatever element carries it. See the dark block
 * below for the full story.
 *
 * Specificity note, because it is the whole mechanism: `[data-theme='harbor']`
 * and `.dark` are BOTH (0,1,0). On `<html data-theme="harbor" class="dark">`
 * the tie is broken by source order — this file is imported after
 * brand/interlace.css — and then `[data-theme='harbor'].dark` (0,2,0) beats
 * everything. That only produces a coherent page because this file defines
 * EVERY token in both blocks: a token missing from the dark block would
 * silently fall through to the harbor LIGHT value sitting one specificity
 * step below it (not to Interlace dark, which is what a reader expects), and
 * a single light-mode surface in an otherwise dark page is exactly the class
 * of defect nobody files a bug for. `theme-contract-lock` is what stops it.
 *
 * ─── The palette ──────────────────────────────────────────────────
 *
 * Deep harbour blue on cool slate. Chosen to be *unmistakably* not
 * Interlace: the brand palette is warm (burnt orange #7d350c, brand green,
 * warm-tinted neutrals #faf7f4 / #4d453c), so Harbor inverts the temperature
 * on every axis — blue primary, blue-grey neutrals, a cool off-white page.
 * A second theme that reads as "the same theme, slightly different" proves
 * nothing about the cascade.
 *
 * Hue separation inside the theme: primary is blue (250°-ish), `--info` is
 * CYAN rather than the usual blue, because an info chip that renders in the
 * primary hue is an info chip nobody can see is an info chip.
 *
 * ─── Contrast (WCAG 2.2 AA, measured — not eyeballed) ─────────────
 *
 * Every pair below is recomputed by `__tests__/theme-contract-lock.test.ts`
 * on every run; these numbers are a reader's convenience, and the test is
 * the authority. Body text ≥ 4.5:1, non-text UI boundaries ≥ 3:1.
 *
 *                                          light      dark
 *   foreground   on background            17.74:1   16.19:1   (AAA)
 *   card-fg      on card                  18.72:1   14.69:1   (AAA)
 *   muted-fg     on background             7.82:1    9.52:1   (AAA)
 *   muted-fg     on muted                  7.34:1    8.64:1   (AAA)
 *   accent-fg    on accent                 8.95:1    9.65:1   (AAA)
 *   primary-fg   on primary                8.86:1   10.03:1   (AAA)
 *   primary      on background             8.39:1   10.03:1   (AAA)
 *   primary      on primary/10 tint        7.15:1    8.42:1   (AAA)
 *   destructive  on background             7.60:1   10.03:1   (AAA)
 *   success      on background             7.28:1    9.86:1   (AAA)
 *   warning      on background             8.60:1    8.83:1   (AAA)
 *   info         on background             6.89:1   13.08:1   (AAA)
 *   caution      on background             8.88:1   11.24:1   (AAA)
 *   hero-fg      on hero-surface          15.76:1   15.76:1   (AAA)
 *   ─ non-text (SC 1.4.11 / SC 2.4.13, floor 3:1) ─
 *   ring         on background             8.39:1   10.03:1
 *   ring         on card                   8.86:1    9.10:1
 *   input        on background             3.43:1    4.25:1
 *   input        on card                   3.62:1    3.85:1
 *   viz-axis     on background             3.57:1    4.84:1
 *   viz-axis     on card                   3.77:1    4.39:1
 *
 * `--border`, `--viz-grid` and `--viz-edge` are deliberately BELOW 3:1 in
 * both schemes (1.2–1.5:1) for the same reason they are in Interlace: they
 * are decorative separators and ambient chart texture, exempt from SC
 * 1.4.11, and a grid that fights the series it exists to support is worse
 * than a faint one.
 */

@layer interlace.brand {
  /* ─────────────────────────────────────────────────────────────────
   *  HARBOR · LIGHT
   * ──────────────────────────────────────────────────────────────── */
  [data-theme='harbor'],
  [data-theme='harbor'] [data-scheme='light'] {
    /* Brand — harbour blue. #0f4c81 is 8.39:1 on the page and 8.86:1 on a
     * card; the binding constraint is the same one Interlace documents,
     * `bg-primary/10 text-primary` (the stock shadcn tinted-chip pattern),
     * which composites to #e0e8ef and still measures 7.15:1 — clear of the
     * AAA floor the Storybook axe gate enforces. */
    --interlace-primary: oklch(0.409 0.1065 250.2);            /* 8.39:1 on background (AAA) */
    --interlace-primary-hover: oklch(0.357 0.0916 250.2);      /* 10.40:1 on background */
    --interlace-primary-active: oklch(0.287 0.0708 249.8);     /* 13.49:1 on background */
    --interlace-primary-foreground: oklch(1 0 0); /* 8.86:1 on primary (AAA) */
    --interlace-primary-subtle: oklch(0.957 0.0127 244.3);     /* cool tint for backgrounds */
    --interlace-primary-subtle-foreground: oklch(0.287 0.0708 249.8); /* 12.59:1 on subtle (AAA) */

    /* Surface — a cool off-white page with pure-white cards, so the card
     * edge reads without leaning on `--border`. (Interlace runs white-on-
     * white and separates with the border; both are valid, and having the
     * two themes differ here is a genuine test of the semantics layer.) */
    --interlace-background: oklch(0.981 0.0034 247.9);
    --interlace-foreground: oklch(0.183 0.0309 263.4);         /* near-black, cool cast */
    --interlace-card: oklch(1 0 0);
    --interlace-card-foreground: oklch(0.183 0.0309 263.4);
    --interlace-popover: oklch(1 0 0);
    --interlace-popover-foreground: oklch(0.183 0.0309 263.4);
    --interlace-muted: oklch(0.959 0.0069 247.9);
    --interlace-muted-foreground: oklch(0.425 0.0307 250.3);   /* 7.82:1 on bg / 7.34:1 on muted (AAA) */
    --interlace-border: oklch(0.916 0.0133 251.6);    /* 1.21:1 on background — decorative separators only, exempt from SC 1.4.11 */
    /* Control BOUNDARY, so SC 1.4.11 applies: ≥3:1 against the adjacent
     * surface, and the adjacent surface is `--card` (#ffffff) as often as
     * it is the page — a form usually lives in a card. Measured on both. */
    --interlace-input: oklch(0.621 0.0261 250.2);              /* 3.43:1 on bg / 3.62:1 on card */
    --interlace-ring: var(--interlace-primary);

    /* Accent */
    --interlace-accent: oklch(0.957 0.0127 244.3);             /* cool tint */
    --interlace-accent-foreground: oklch(0.377 0.0933 247.8);  /* 8.95:1 on accent (AAA) */

    /* Secondary */
    --interlace-secondary: oklch(0.959 0.0069 247.9);
    --interlace-secondary-foreground: oklch(0.239 0.0256 251.3); /* 14.63:1 on secondary (AAA) */

    /* Destructive — rose-800 rather than Interlace's red-800. On a cool
     * palette a pure red reads as a stray warm accent; rose keeps the
     * magenta lean that sits with blue. 7.60:1 on background. */
    --interlace-destructive: oklch(0.455 0.1713 13.7);
    --interlace-destructive-foreground: oklch(1 0 0); /* 8.02:1 on destructive */

    /* Success — emerald-800, shared with Interlace. Green is the one status
     * hue with no cool/warm variant worth having: it must stay far from
     * both the blue primary and the amber warning, and emerald already is. */
    --interlace-success: oklch(0.432 0.0865 166.9);
    --interlace-success-foreground: oklch(1 0 0); /* 7.68:1 on success */

    /* Warning — amber-900. Same reasoning as Interlace: yellow cannot
     * physically clear 7:1 on a light page at its brand-bright value, so
     * the TEXT token is the deep amber and bright yellow stays a surface. */
    --interlace-warning: oklch(0.414 0.1054 45.9);
    --interlace-warning-foreground: oklch(1 0 0); /* 9.07:1 on warning */

    /* Info — CYAN (cyan-800), not blue. See the header note: in a
     * blue-primary theme, a blue info token is indistinguishable from
     * primary, which is the whole job of the token. */
    --interlace-info: oklch(0.45 0.0771 224.3);
    --interlace-info-foreground: oklch(1 0 0);    /* 7.27:1 on info */

    /* Caution — the rung between warning and destructive. orange-900,
     * shared with Interlace: the ladder needs five separable tones and
     * this is the only warm rung Harbor keeps. */
    --interlace-caution: oklch(0.408 0.1165 38.2);
    --interlace-caution-foreground: oklch(1 0 0); /* 9.37:1 on caution */

    /* Highlight — amber-300, shared with Interlace: a warm call-to-action
     * that stands apart from Harbor's blue primary. */
    --interlace-highlight: oklch(0.879 0.1534 91.6);
    --interlace-highlight-foreground: oklch(0.216 0.0061 56); /* 12.1:1 on highlight */

    /* Scrim — sits on a consumer-supplied photo, so it does not invert and
     * it does not take the theme's temperature either. Always used with an
     * alpha modifier (`bg-scrim/70`). */
    --interlace-scrim: oklch(0 0 0);
    --interlace-scrim-foreground: oklch(1 0 0);

    /* Cosmic hero effects — the starfield's three painted colours. Harbor
     * runs a blue star / cyan trail against the same always-dark hero. */
    --interlace-hero-star: oklch(0.82 0.0913 255.8);
    --interlace-hero-trail: oklch(0.797 0.1339 211.5);
    --interlace-hero-meteor: oklch(0.927 0.0362 252.1);

    /* Cosmic hero surface — its OWN surface, not a themed one: a starfield
     * only reads as a starfield on near-black, so this does not invert with
     * the scheme. #e6eef7 on #0a1424 measures 15.76:1 (AAA). */
    --interlace-hero-surface: oklch(0.191 0.0359 259.5);
    --interlace-hero-surface-deep: oklch(0 0 0);
    --interlace-hero-foreground: oklch(0.946 0.0149 251.2);

    /* Window controls — the macOS traffic lights the CodeWindow chrome is
     * quoting. These are system colours, not brand colours: a theme that
     * recolours them stops quoting macOS and starts inventing an OS. */
    --interlace-window-control-close: oklch(0.694 0.1964 26.4);
    --interlace-window-control-minimize: oklch(0.835 0.1612 80.9);
    --interlace-window-control-zoom: oklch(0.728 0.2173 144.7);

    /* Chart palette — five separable hues at the same lightness the
     * Interlace ladder uses (L 0.55 light), rotated into the cool half of
     * the wheel with one warm outlier so a five-series chart still reads
     * in greyscale by ordering. */
    /* Strands — harbor inverts the interlace temperatures: strand-a is
     * the harbour blue itself, strand-b the warm counter (hue 41 — not
     * amber ~70, which is the warning status hue). */
    --interlace-strand-a: oklch(0.55 0.15 250);
    --interlace-strand-b: oklch(0.55 0.14 41);

    --interlace-chart-1: oklch(0.55 0.15 250);  /* harbour blue */
    --interlace-chart-2: oklch(0.55 0.12 200);  /* cyan */
    --interlace-chart-3: oklch(0.55 0.14 155);  /* sea green */
    --interlace-chart-4: oklch(0.55 0.16 300);  /* violet */
    --interlace-chart-5: oklch(0.55 0.15 350);  /* rose */

    /* Visualisation chrome — what the series are drawn ON.
     *   grid  #dde4ec → 1.21:1 on bg / 1.28:1 on card   DECORATIVE
     *                          (never the sole carrier of a value)
     *   axis  #788593 → 3.57:1 on bg / 3.77:1 on card — STRUCTURAL, SC 1.4.11
     *   edge  #dde4ec → 1.21:1 on bg / 1.28:1 on card   ambient texture
     * Perceptual weights matched to Interlace (1.39 / 3.64 / 1.39) so a
     * chart does not read as heavier in one theme than the other. */
    --interlace-viz-grid: oklch(0.916 0.0133 251.6);
    --interlace-viz-axis: oklch(0.611 0.0262 250.2);
    --interlace-viz-edge: oklch(0.916 0.0133 251.6);

    /* Radius — structural, not brand. Harbor keeps Interlace's base: a
     * theme that also moves the geometry is two changes wearing one name. */
    --interlace-radius: 0.75rem;

    /* Brand mark — the two bars of the mark. Decorative fills, so they
     * track the theme's identity pair rather than the AAA text ramp. */
    --interlace-brand-mark-bar-o: oklch(0.569 0.2023 259.7);
    --interlace-brand-mark-bar-g: oklch(0.52 0.0936 223.1);
  }

  /* ─────────────────────────────────────────────────────────────────
   *  HARBOR · DARK
   *
   *  Both spellings of the scheme axis, exactly as brand/interlace.css
   *  declares them — `.dark` (shadcn / next-themes canon, what the
   *  Storybook decorator and every consumer writes) and the attribute
   *  form for hosts that would rather not touch className.
   *
   *  ─── Why the DESCENDANT forms are here too ──────────────────────
   *
   *  `.dark` in brand/interlace.css is unscoped, so what it really means
   *  is "INTERLACE dark" — it re-declares every `--interlace-*` literal on
   *  whatever element carries it. A `.dark` on a SUBTREE of a Harbor page
   *  therefore silently resets that subtree to the Interlace palette:
   *  `[data-theme='harbor'].dark` needs both on the SAME element, and a
   *  wrapper div has only the class.
   *
   *  Found in a browser (Phase 8.4): ds.interlace.tools in Harbor, with an
   *  embedded Storybook preview whose story wraps itself in
   *  `<div class="dark">` — navy page, burnt-orange button. It reads as
   *  "the theme did not apply", and it is not a story artefact: any
   *  consumer that darkens a panel rather than the document hits it.
   *
   *  So a theme claims its whole subtree. `[data-theme='harbor'] .dark`
   *  is (0,2,0) — it out-specifies the bare `.dark` (0,1,0) it is
   *  correcting, and ties with `[data-theme='harbor'].dark`, which is
   *  fine: they declare identical values and cannot both match the same
   *  element anyway. Every future theme owes the same two lines; the
   *  selector table in `__tests__/theme-contract-lock.test.ts` is where
   *  that is checked.
   * ──────────────────────────────────────────────────────────────── */
  [data-theme='harbor'].dark,
  [data-theme='harbor'][data-scheme='dark'],
  [data-theme='harbor'] .dark,
  [data-theme='harbor'] [data-scheme='dark'] {
    /* Brand — inverted weight: a light tint of the same harbour blue, so
     * both directions clear AAA. text-primary on the page is 10.03:1, and
     * a filled `bg-primary` chip with `text-primary-foreground` is the same
     * 10.03:1 — the pair holds in both directions. */
    --interlace-primary: oklch(0.794 0.086 245.4);            /* 10.03:1 on background (AAA) */
    --interlace-primary-hover: oklch(0.85 0.0648 245.1);      /* 12.08:1 */
    --interlace-primary-active: oklch(0.9 0.0445 244.1);     /* 14.14:1 */
    --interlace-primary-foreground: oklch(0.175 0.0338 254.1); /* 10.03:1 on primary */
    --interlace-primary-subtle: oklch(0.286 0.063 249.1);
    --interlace-primary-subtle-foreground: oklch(0.9 0.0445 244.1); /* 10.65:1 on subtle (AAA) */

    /* Surface — deep navy-black rather than Interlace's warm near-black. */
    --interlace-background: oklch(0.175 0.0338 254.1);
    --interlace-foreground: oklch(0.946 0.0149 251.2);
    --interlace-card: oklch(0.223 0.0371 252.7);
    --interlace-card-foreground: oklch(0.946 0.0149 251.2);
    --interlace-popover: oklch(0.223 0.0371 252.7);
    --interlace-popover-foreground: oklch(0.946 0.0149 251.2);
    --interlace-muted: oklch(0.223 0.0371 252.7);
    --interlace-muted-foreground: oklch(0.781 0.0343 248.3);   /* 9.52:1 on bg / 8.64:1 on card (AAA) */
    --interlace-border: oklch(0.284 0.0397 252.1);    /* 1.32:1 on background — decorative separators only */
    --interlace-input: oklch(0.569 0.0357 251.3);              /* 4.25:1 on bg / 3.85:1 on card (SC 1.4.11) */
    --interlace-ring: var(--interlace-primary);

    /* Accent */
    --interlace-accent: oklch(0.286 0.063 249.1);
    --interlace-accent-foreground: oklch(0.869 0.0567 247.7);  /* 9.65:1 on accent (AAA) */

    /* Secondary */
    --interlace-secondary: oklch(0.24 0.0336 254.5);
    --interlace-secondary-foreground: oklch(0.946 0.0149 251.2); /* 14.04:1 on secondary (AAA) */

    /* Destructive — rose-300, the dark twin of the light rose-800. */
    --interlace-destructive: oklch(0.81 0.1061 11.6);        /* 10.03:1 on background (AAA) */
    --interlace-destructive-foreground: oklch(0.175 0.0338 254.1);

    /* Success — emerald-400. */
    --interlace-success: oklch(0.773 0.1535 163.2);            /* 9.86:1 on background (AAA) */
    --interlace-success-foreground: oklch(0.266 0.0628 152.9);

    /* Warning — amber-500. Yellows are physically easier on dark surfaces,
     * so no bump is needed: 8.83:1 on the page. */
    --interlace-warning: oklch(0.769 0.1647 70.1);
    --interlace-warning-foreground: oklch(0.187 0.0383 89.1);

    /* Info — cyan-300, holding the hue separation from the blue primary
     * that the light block explains. */
    --interlace-info: oklch(0.865 0.1153 207.1);               /* 13.08:1 on background (AAA) */
    --interlace-info-foreground: oklch(0.175 0.0338 254.1);

    /* Caution — orange-300, the dark rung between warning and destructive. */
    --interlace-caution: oklch(0.837 0.1165 66.3);            /* 11.24:1 on background (AAA) */
    --interlace-caution-foreground: oklch(0.175 0.0338 254.1);

    /* Highlight — amber-400, the dark twin. */
    --interlace-highlight: oklch(0.837 0.1644 84.4);
    --interlace-highlight-foreground: oklch(0.175 0.0338 254.1); /* 11.4:1 on highlight */

    /* ── Scheme-invariant tokens, restated ──────────────────────────
     * Same values as the light block by design (a scrim is dark because it
     * sits on a photo; the cosmic hero paints its own near-black surface in
     * either scheme; radii are structure, not colour). Restated rather than
     * inherited so that every theme × scheme block is a COMPLETE override
     * surface — which is what makes THEME_TOKENS checkable, and what tells
     * the next reader "deliberately the same" instead of "forgotten". */
    --interlace-scrim: oklch(0 0 0);
    --interlace-scrim-foreground: oklch(1 0 0);

    --interlace-hero-star: oklch(0.82 0.0913 255.8);
    --interlace-hero-trail: oklch(0.797 0.1339 211.5);
    --interlace-hero-meteor: oklch(0.927 0.0362 252.1);

    --interlace-hero-surface: oklch(0.191 0.0359 259.5);
    --interlace-hero-surface-deep: oklch(0 0 0);
    --interlace-hero-foreground: oklch(0.946 0.0149 251.2);    /* 15.76:1 on the surface (AAA) */

    --interlace-radius: 0.75rem;

    --interlace-window-control-close: oklch(0.694 0.1964 26.4);
    --interlace-window-control-minimize: oklch(0.835 0.1612 80.9);
    --interlace-window-control-zoom: oklch(0.728 0.2173 144.7);

    /* Chart palette — same five hues, lifted to L 0.78 so each series stays
     * clear of the dark card, matching the Interlace dark ladder. */
    /* Strands — lighter tints of the same inverted pair */
    --interlace-strand-a: oklch(0.78 0.13 250);
    --interlace-strand-b: oklch(0.78 0.12 41);

    --interlace-chart-1: oklch(0.78 0.13 250);  /* harbour blue */
    --interlace-chart-2: oklch(0.78 0.11 200);  /* cyan */
    --interlace-chart-3: oklch(0.78 0.12 155);  /* sea green */
    --interlace-chart-4: oklch(0.78 0.14 300);  /* violet */
    --interlace-chart-5: oklch(0.78 0.13 350);  /* rose */

    /* Visualisation chrome — dark, measured against BOTH dark surfaces
     * because a chart normally renders inside a Card, not on the page:
     *   grid  #25344a → 1.51:1 on bg / 1.37:1 on card   DECORATIVE
     *   axis  #71829a → 4.84:1 on bg / 4.39:1 on card   clears SC 1.4.11
     *   edge  #25344a → 1.51:1 on bg / 1.37:1 on card   ambient */
    --interlace-viz-grid: oklch(0.322 0.0443 257.8);
    --interlace-viz-axis: oklch(0.602 0.0418 257);
    --interlace-viz-edge: oklch(0.322 0.0443 257.8);

    /* Brand mark — brighter pair for dark chrome. */
    --interlace-brand-mark-bar-o: oklch(0.794 0.086 245.4);
    --interlace-brand-mark-bar-g: oklch(0.865 0.1153 207.1);
  }
}

/*
 * @interlace/ui — SEMANTICS: the names components read.
 *
 * Layer 2 of 4 (brand → semantics → structure → page). Binds every semantic
 * name, shadcn's (`--primary`, `--background`, …) and Interlace's own
 * (`--success`, `--caution`, `--scrim`, `--viz-*`, …), to a brand token,
 * then registers each as a Tailwind colour so `bg-primary` and `text-success`
 * exist. Components read these names and only these; a raw `--interlace-*`
 * in a component is a layering leak.
 *
 * Bindings live in `@layer interlace.semantics`, so a host app's unlayered
 * `:root { --primary: … }` (every shadcn app has one) wins. The `@theme
 * inline` registration stays top-level: Tailwind processes it globally.
 */

@layer interlace.semantics {
  /* ─────────────────────────────────────────────────────────────────
   *  Bind brand tokens to the shadcn-bare semantic names. Apps that want
   *  to override individual semantic values can re-declare them either
   *  here (`@layer interlace.semantics { :root { --background: ... } }`)
   *  AFTER importing this file, or they can fork the entire brand layer
   *  upstream (`@layer interlace.brand { ... }`) to swap the underlying
   *  colour values without touching the alias graph.
   *
   *  WHY FOUR SELECTORS AND NOT JUST `:root`. A custom property whose
   *  value is a `var()` is substituted at computed-value time on the
   *  element that DECLARES it, then inherited as a resolved value. So
   *  `:root { --primary: var(--interlace-primary) }` freezes whatever
   *  `--interlace-primary` is on the root. If a subtree re-brands itself
   *  (`<div class="dark">` — which is exactly what a Storybook decorator
   *  or a side-by-side theme preview does), the brand token changes on
   *  that div while `--primary` stays frozen at the root's value, and
   *  nothing repaints. Re-binding on every element that can carry a brand
   *  override is what makes subtree theming work.
   *
   *  `[data-theme]` is attribute-presence, not a value match: it covers
   *  every theme file that ever ships, so adding themes/<name>.css needs
   *  no edit here. THIS LIST IS THE COMPLETE SET OF BRAND-OVERRIDE
   *  SELECTORS — a new one must be added here too, or its subtree will
   *  render the parent's semantics over the child's brand.
   * ──────────────────────────────────────────────────────────────── */
  :root,
  .dark,
  [data-scheme='dark'],
  [data-scheme='light'],
  [data-theme] {
    --primary: var(--interlace-primary);
    --primary-foreground: var(--interlace-primary-foreground);
    --background: var(--interlace-background);
    --foreground: var(--interlace-foreground);
    --card: var(--interlace-card);
    --card-foreground: var(--interlace-card-foreground);
    --popover: var(--interlace-popover);
    --popover-foreground: var(--interlace-popover-foreground);
    --muted: var(--interlace-muted);
    --muted-foreground: var(--interlace-muted-foreground);
    --accent: var(--interlace-accent);
    --accent-foreground: var(--interlace-accent-foreground);
    --secondary: var(--interlace-secondary);
    --secondary-foreground: var(--interlace-secondary-foreground);
    --border: var(--interlace-border);
    --input: var(--interlace-input);
    --ring: var(--interlace-ring);
    --destructive: var(--interlace-destructive);
    --destructive-foreground: var(--interlace-destructive-foreground);
    --radius: var(--interlace-radius);

    /* Status semantics — NEW. Surfaces success / warning / info as
     * shadcn-bare token names so consumers reach for `bg-success`,
     * `text-warning`, `bg-info` instead of `bg-emerald-700` /
     * `bg-amber-500` / `bg-blue-600`. Brand fork-friendly: override
     * `--interlace-success` / `-warning` / `-info` in
     * `@layer interlace.brand` to swap the underlying colour. */
    --success: var(--interlace-success);
    --success-foreground: var(--interlace-success-foreground);
    --warning: var(--interlace-warning);
    --warning-foreground: var(--interlace-warning-foreground);
    --info: var(--interlace-info);
    --info-foreground: var(--interlace-info-foreground);
    --caution: var(--interlace-caution);
    --caution-foreground: var(--interlace-caution-foreground);
    --highlight: var(--interlace-highlight);
    --highlight-foreground: var(--interlace-highlight-foreground);

    --scrim: var(--interlace-scrim);
    --scrim-foreground: var(--interlace-scrim-foreground);
    --hero-star: var(--interlace-hero-star);
    --hero-trail: var(--interlace-hero-trail);
    --hero-meteor: var(--interlace-hero-meteor);
    --hero-surface: var(--interlace-hero-surface);
    --hero-surface-deep: var(--interlace-hero-surface-deep);
    --hero-foreground: var(--interlace-hero-foreground);

    /* Window-control dots — unprefixed names so the CodeWindow chrome can be
     * lifted into a consumer that defines only these three properties. */
    --window-control-close: var(--interlace-window-control-close);
    --window-control-minimize: var(--interlace-window-control-minimize);
    --window-control-zoom: var(--interlace-window-control-zoom);

    /* Chart palette — semantic aliases of the brand layer. Overrides
     * the bridge layer (theme.css) values, so a consumer who wants
     * different chart hues forks `@layer interlace.brand` to set
     * `--interlace-chart-N` and the `--chart-N` token flows through. */
    /* Strand pair — the woven brand gesture (BRAND_PHILOSOPHY.md) */
    --strand-a: var(--interlace-strand-a);
    --strand-b: var(--interlace-strand-b);

    --chart-1: var(--interlace-chart-1);
    --chart-2: var(--interlace-chart-2);
    --chart-3: var(--interlace-chart-3);
    --chart-4: var(--interlace-chart-4);
    --chart-5: var(--interlace-chart-5);

    /* Visualisation semantics — the chart's non-series vocabulary.
     *
     * Declared HERE and not in `theme.css`, on purpose: `--chart-N` is a
     * shadcn-bare name the bridge layer must supply for stock shadcn chart
     * code, but `--viz-*` is Interlace-original. `index.css` imports both, so
     * every consumer on the canonical one-line import gets it.
     *
     * Three resolve to brand colours (grid / axis / edge — contrast tables above).
     * Every other one is an ALIAS of a token whose contrast is already verified
     * in both themes. Deliberate: a diverging red/green scale that drifts away
     * from `--success` / `--destructive` is how a product ends up with two
     * greens that mean "good". One fork surface, one green. */
    --viz-grid: var(--interlace-viz-grid);
    --viz-axis: var(--interlace-viz-axis);
    --viz-edge: var(--interlace-viz-edge);

    /* Meaning-bearing marks — each an existing, verified token. */
    --viz-edge-active: var(--primary);
    --viz-node: var(--muted-foreground);
    --viz-node-active: var(--primary);
    --viz-crosshair: var(--muted-foreground);

    /* Direction. NOTE FOR COMPONENT AUTHORS: colour must never be the only
     * signal — red/green is invisible to ~8% of men. Every component using
     * these also prints a sign, an arrow, or a shape. See
     * docs/philosophies/VISUALIZATION_PHILOSOPHY.md. */
    --viz-positive: var(--success);
    --viz-negative: var(--destructive);
    --viz-neutral: var(--muted-foreground);

    /* Threshold / target bands drawn behind the series. Alpha-composited off
     * `--foreground` so it tracks the theme instead of needing a pair. */
    --viz-band: color-mix(in srgb, var(--foreground) 6%, transparent);

    /* Annotations — an action drawn ON the curve. Three kinds, three verified
     * hues, distinguished by marker SHAPE as well as hue (shape is what
     * survives greyscale). */
    --viz-annotation-publish: var(--primary);
    --viz-annotation-release: var(--info);
    --viz-annotation-action: var(--warning);

    /* Override fumadocs-prefixed tokens for AA contrast.
     *
     * Fumadocs `neutral.css` ships `--color-fd-muted-foreground: #737373`,
     * which yields 4.34–4.46:1 contrast against the `bg-fd-card/40-50`
     * surfaces our Section / SectionHeader stories render — just below
     * the WCAG 2.2 AA 4.5:1 floor and gates Storybook a11y CI red.
     *
     * Rebinding to the brand muted-foreground (a darker warm grey in
     * light, lighter in dark) clears the threshold and keeps brand
     * consistency between shadcn-styled and fumadocs-styled surfaces.
     */
    --color-fd-muted-foreground: var(--interlace-muted-foreground);

    /* Brand mark bar fills — the UNPREFIXED names are the cross-repo
     * contract: brand-logo.tsx and the eslint docs site both read
     * `var(--brand-mark-bar-*)`, so a consumer outside this monorepo can
     * define just these two properties and render the same lockup. */
    --brand-mark-bar-o: var(--interlace-brand-mark-bar-o);
    --brand-mark-bar-g: var(--interlace-brand-mark-bar-g);
  }
}

/* Register the shadcn-bare tokens as Tailwind v4 theme keys so utilities
 * like `bg-card`, `text-foreground`, `border-border`, `bg-primary` are
 * generated. `inline` preserves the `var()` reference, so the runtime
 * `.dark { --background: ... }` overrides above flow through to every
 * utility. Without this block, Tailwind v4 emits no `bg-card` rule
 * regardless of what `--card` resolves to on :root.
 *
 * STAYS AT TOP LEVEL (NOT inside `@layer`): Tailwind v4's `@theme`
 * directive is a special generator — it registers tokens AND emits
 * utility rules in Tailwind's own `theme` / `utilities` layers. Wrapping
 * it in a custom `@layer interlace.*` block breaks that processing. The
 * cascade-layer story applies to the alias bindings above, not to the
 * token-registration directive. */
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  /* Status semantics — generates bg-success, text-warning, bg-info,
   * border-info etc. */
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-info: var(--info);
  --color-info-foreground: var(--info-foreground);
  --color-caution: var(--caution);
  --color-caution-foreground: var(--caution-foreground);
  --color-highlight: var(--highlight);
  --color-highlight-foreground: var(--highlight-foreground);

  /* Scrim — generates bg-scrim/70, text-scrim-foreground,
   * border-scrim-foreground/30 so image-overlay surfaces stop reaching for
   * `bg-black/70` + `text-white` palette escapes. */
  --color-scrim: var(--scrim);
  --color-scrim-foreground: var(--scrim-foreground);

  /* Cosmic-hero surface — generates bg-hero-surface / text-hero-foreground
   * so HeroCosmic paints its always-dark surface from tokens instead of
   * `via-slate-950 to-black` palette escapes. */
  --color-hero-surface: var(--hero-surface);
  --color-hero-surface-deep: var(--hero-surface-deep);
  --color-hero-foreground: var(--hero-foreground);

  /* Window-control dots — generates bg-window-control-close etc. so the
   * CodeWindow chrome stays inside the Tailwind utility surface (R18/R19)
   * instead of reaching for `bg-[#ff5f57]`. */
  --color-window-control-close: var(--window-control-close);
  --color-window-control-minimize: var(--window-control-minimize);
  --color-window-control-zoom: var(--window-control-zoom);

  /* Chart palette utilities — generates bg-chart-1, text-chart-2,
   * border-chart-3 etc. Already declared in theme.css (bridge layer);
   * re-declared here at semantics-layer priority so brand overrides
   * propagate. */
  /* Strand utilities — generates stroke-strand-a, text-strand-a etc.
   * for the woven brand gestures (BRAND_PHILOSOPHY.md). */
  --color-strand-a: var(--strand-a);
  --color-strand-b: var(--strand-b);

  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  /* Visualisation utilities — generates stroke-viz-axis, fill-viz-band,
   * text-viz-positive, bg-viz-grid etc. Charts are SVG, so `stroke-*` and
   * `fill-*` are the utilities actually used; Tailwind emits them from the
   * same `--color-*` registration as `bg-*` / `text-*`. */
  --color-viz-grid: var(--viz-grid);
  --color-viz-axis: var(--viz-axis);
  --color-viz-edge: var(--viz-edge);
  --color-viz-edge-active: var(--viz-edge-active);
  --color-viz-node: var(--viz-node);
  --color-viz-node-active: var(--viz-node-active);
  --color-viz-crosshair: var(--viz-crosshair);
  --color-viz-positive: var(--viz-positive);
  --color-viz-negative: var(--viz-negative);
  --color-viz-neutral: var(--viz-neutral);
  --color-viz-band: var(--viz-band);
  --color-viz-annotation-publish: var(--viz-annotation-publish);
  --color-viz-annotation-release: var(--viz-annotation-release);
  --color-viz-annotation-action: var(--viz-annotation-action);
}

/*
 * @interlace/ui — STRUCTURE / type: the type scale and reading classes.
 *
 * Layer 3 of 4 (brand → semantics → structure → page). Brand-invariant:
 * no colour, no `--interlace-*`. Every key here is NEW to Tailwind (text-h1,
 * text-body, leading-long, tracking-display, font-body), so it adds
 * utilities without replacing any. The typefaces themselves are opt-in, in
 * page/fonts.css.
 *
 * Sources: TYPOGRAPHY_PHILOSOPHY.md (type scale, body/code contracts, fluid
 * type, reading-vs-UI modes).
 */

@theme {
  /* ── Font families ─────────────────────────────────────────────── */
  /* Two new keys, both additive. Components read `font-body` for text and
     `font-heading` for headings; neither picks a typeface. `font-body`
     follows the app's own `font-sans`, and `font-heading` follows
     `font-body`, so an app that never touches them gets its own typeface
     everywhere. Re-point either one to change components only:
       @theme { --font-heading: var(--font-serif); }
     That one line is the editorial look: serif headings (Typography h1–h6,
     CardTitle, every pattern title) over the sans body.
     The Interlace typefaces (Inter, JetBrains Mono) are opt-in, in
     page/fonts.css, because they replace the app's `font-sans`. */
  --font-body: var(--font-sans);
  --font-heading: var(--font-body);

  /* ── Type scale (font-size + paired line-height) ───────────────────
     SIX heading levels max (TYPOGRAPHY "heading scale"). Display end fluids
     on a single curve; body stays FIXED (no clamp on body — confuses readers).
     Generates text-h1…text-h6, text-body, text-long, text-ui, text-code, etc. */
  --text-h1: clamp(2.5rem, 4vw + 1rem, 3.5rem); /* 40 → 56px */
  --text-h1--line-height: 1.1;
  --text-h2: 1.875rem; /* 30px */
  --text-h2--line-height: 1.2;
  --text-h3: 1.5rem; /* 24px */
  --text-h3--line-height: 1.25;
  --text-h4: 1.25rem; /* 20px */
  --text-h4--line-height: 1.3;
  --text-h5: 1.0625rem; /* 17px */
  --text-h5--line-height: 1.4;
  --text-h6: 1rem; /* 16px */
  --text-h6--line-height: 1.4;
  --text-body: 1rem; /* 16px base body */
  --text-body--line-height: 1.6;
  --text-long: 1.0625rem; /* 17px long-form reading */
  --text-long--line-height: 1.7;
  --text-ui: 0.875rem; /* 14px UI text */
  --text-ui--line-height: 1.5;
  --text-ui-sm: 0.8125rem; /* 13px dense UI */
  --text-ui-sm--line-height: 1.5;
  --text-code: 0.875rem; /* 14px code blocks */
  --text-code--line-height: 1.6;
  --text-caption: 0.8125rem; /* 13px captions / eyebrows */
  --text-caption--line-height: 1.5;

  /* ── Line-height scale (standalone leading-* utilities) ─────────── */
  --leading-body: 1.6;
  --leading-long: 1.7;
  --leading-ui: 1.5;
  --leading-heading: 1.2;

  /* ── Letter-spacing (tracking-* utilities) ─────────────────────────
     0 body; tighten only headings ≥32px. */
  --tracking-display: -0.02em;
  --tracking-heading: -0.01em;

  /* Weight ladder (TYPOGRAPHY "weight ladder"): 400 body / 500 UI emphasis /
     600 strong + headings / 700 page headings — NO 900 ever. Uses Tailwind's
     built-in font-normal/font-medium/font-semibold/font-bold; NOT redefined as
     --font-weight-* tokens (those would collide with the --font-* family keys
     on the shared `font-<name>` utility namespace). */

}

/* ── Reading-mode vs UI-mode component classes ──────────────────────
   TYPOGRAPHY "Reading mode vs UI mode": the call site declares intent.
   The Typography primitive applies the right class by default; consumers
   reach for these directly on prose containers. Body is FIXED size (never
   fluid); measure is bounded ≤75ch (non-negotiable). */
@layer components {
  .prose-body {
    font-family: var(--font-body);
    font-size: var(--text-body);
    line-height: var(--leading-body);
    max-width: 65ch;
  }
  .prose-long {
    font-family: var(--font-body);
    font-size: var(--text-long);
    line-height: var(--leading-long);
    max-width: 75ch;
    text-rendering: optimizeLegibility;
  }
  .ui-text {
    font-family: var(--font-body);
    font-size: var(--text-ui);
    line-height: var(--leading-ui);
  }
  .ui-text-sm {
    font-family: var(--font-body);
    font-size: var(--text-ui-sm);
    line-height: var(--leading-ui);
  }
}

/*
 * @interlace/ui — STRUCTURE / radius: the `rounded-*` scale from `--radius`.
 *
 * Layer 3 of 4 (brand → semantics → structure → page). One knob: the
 * brand sets `--interlace-radius`, semantics.css binds `--radius` to it,
 * and these four keys derive from `--radius`.
 */

/* ── Radius: derived from the `--radius` CSS variable ───────────────────
   The same derivation shadcn writes into every app, so in a shadcn app
   these keys agree with the app's own and `--radius` is the one knob.
   Written character for character as shadcn writes them, so a shadcn app
   compiles `rounded-*` exactly as it did before Interlace arrived. An app
   without `--radius` gets it from semantics.css.
   Interlace sets --interlace-radius to 0.75rem (brand/interlace.css):
   sm 8px · md 10px · lg 12px · xl 16px. */
@theme inline {
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

/*
 * @interlace/ui — STRUCTURE / motion: animation tokens, keyframes, classes,
 * and the reduced-motion allowlist.
 *
 * Layer 3 of 4 (brand → semantics → structure → page). No colour. Every
 * `--animate-*` key is one Tailwind and tw-animate-css do not ship, so it
 * adds utilities without replacing any.
 */

/* Motion tokens. `@theme` (not inline) so a brand can override any of them
 * on :root and every utility follows. The eases become Tailwind utilities
 * (`ease-enter`, `ease-exit`, `ease-move`); the durations are used as
 * `duration-(--duration-fast)`. Bands and use: MOTION_PHILOSOPHY.md. */
@theme {
  /* Appear: fast out of the gate, a long soft landing (expo-out family). */
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  /* Leave: starts slow, gets out of the way (quart-in family). */
  --ease-exit: cubic-bezier(0.5, 0, 0.75, 0);
  /* Move between two resting places, both ends eased. */
  --ease-move: cubic-bezier(0.65, 0, 0.35, 1);
}

:root {
  --duration-fast: 100ms;
  --duration-base: 150ms;
  --duration-medium: 250ms;
  --duration-slow: 400ms;
}

@theme inline {
  /* Primitives: accordion — `animate-accordion-down/up` come from
     tw-animate-css, which the base item depends on. Declaring them here
     too replaced tw-animate's version in every shadcn app (losing its
     duration/ease modifiers) for an identical keyframe. */

  /* Interlace: the draw verb (BRAND_PHILOSOPHY §2) — a strand drawn,
   * never faded. Paths normalize with pathLength=100 so one keyframe
   * serves every geometry; 600ms is the doctrine's motion ceiling.
   * Pure CSS on purpose: it runs with zero client JS and the preflight
   * reduced-motion clamp reaches it (instantly-drawn end state). */
  --animate-strand-draw: strand-draw 600ms ease-out forwards;

  /* The draw verb's second mechanism, for a chart whose dash pattern IS
   * series identity (TimeSeries): stroke-dashoffset would overwrite the
   * dashes, so the true paths are progressively REVEALED by a clip rect
   * that scales open left→right — the shuttle pass. The transform moves
   * a CLIP EDGE, never content (the motion lock verifies the utility
   * only ever lands on a clipPath child). From-only keyframe on
   * purpose: the rect RESTS fully open, so with no animation at all
   * (reduced motion, jsdom, an engine that cannot animate clip
   * contents) nothing is ever hidden. Same 600ms draw ceiling.
   *
   * Declared ABOVE the keyframes bodies: the motion lock's segmenter
   * runs each @keyframes to the next header, and a declaration sitting
   * between two bodies would be over-captured into the first one. */
  --animate-weave-reveal: weave-reveal 600ms ease-out;

  /* The draw verb as a loading state (ThreadMark `drawing`): the woven
   * pair draws in, then draws out ahead of itself, and starts again. An
   * ambient loop, so it is exempt from the draw ceiling and named in the
   * reduced-motion list below, where `animation: none` rests it at the
   * element's own dashoffset (0): fully woven and still. */
  --animate-strand-loop: strand-loop 1.6s ease-in-out infinite;

  @keyframes strand-draw {
    from {
      stroke-dashoffset: 100;
    }
    to {
      stroke-dashoffset: 0;
    }
  }

  @keyframes strand-loop {
    0% {
      stroke-dashoffset: 100;
    }
    50% {
      stroke-dashoffset: 0;
    }
    100% {
      stroke-dashoffset: -100;
    }
  }

  @keyframes weave-reveal {
    from {
      transform: scaleX(0);
    }
  }

}

/* ─────────────────────────────────────────────────────────────────
 * Entry animations — fade-in-up / slide-in-left / scale-in.
 *    Reduced-motion: the allowlist below names all three.
 *
 *    All three are ENTRY animations: fill mode `both`, starting from
 *    `opacity: 0`. Nothing the reader came for is legible until they
 *    finish, so MOTION_PHILOSOPHY caps them at 200ms and forbids an entry
 *    delay outright — a delay is dead time where the content is already
 *    painted at `opacity: 0` and the reader is looking at nothing.
 *
 *    They shipped at 0.5s / 0.5s+0.3s / 0.4s+0.2s, i.e. up to 800ms of
 *    invisible hero. `motion-contract-lock` now recomputes these numbers
 *    from this file, so the next 0.5s has to argue with a red test rather
 *    than with a reviewer's memory of the budget.
 * ──────────────────────────────────────────────────────────────── */
@keyframes fade-in-up {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes slide-in-left {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
@keyframes scale-in {
  from {
    opacity: 0;
    transform: scale(0.9);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@layer components {
.animate-fade-in-up {
  animation: fade-in-up 0.2s ease-out both;
}
.animate-slide-in-left {
  animation: slide-in-left 0.2s ease-out both;
}
.animate-scale-in {
  animation: scale-in 0.2s ease-out both;
}
} /* end @layer components */

@layer components {
/*
 * Accessibility — respect prefers-reduced-motion.
 * Industry-canon practice (MUI, Vercel, Linear, Stripe, GitHub all do this).
 * Disables every CSS-driven animation registered above when the user has
 * motion-sensitivity preferences. JS-driven motion (motion/react, canvas)
 * is gated per-component via the useReducedMotion hook.
 *
 * ⚠️ THIS LIST IS THE SECOND LAYER, NOT THE FIRST.
 *
 * The primary reduced-motion guarantee is the wildcard in `page/preflight.css`
 * (`*, *::before, *::after { animation-duration: 0.01ms !important; … }`),
 * and it is the only thing that reaches the animations no selector here can
 * name: Tailwind's own `animate-pulse` / `animate-bounce`, and the
 * `data-[open]:animate-in` / `data-[closed]:animate-out` variants that every
 * Dialog, Sheet, Popover, Tooltip, DropdownMenu and ContextMenu emits (those
 * compile to `.data-\[open\]\:animate-in`, which `.animate-in` does not
 * match). Delete the preflight wildcard and most of the DS starts animating
 * under `reduce` with nothing here to catch it — `motion-contract-lock`
 * fails if anyone tries.
 *
 * What this list buys on top of the wildcard is worth having, which is why
 * both exist:
 *   1. `animation: none` instead of a 0.01ms clamp — the animation never
 *      runs at all, rather than running one imperceptible cycle.
 *   2. cover for the à-la-carte import path. Every stylesheet here is a
 *      separate `exports` entry, so a consumer can import base.css and
 *      skip page/preflight.css; then this list is the ONLY defence.
 *
 * Rule for adding to it: every bare `animate-*` utility that `packages/ui/src`
 * puts on an element belongs here. `.animate-pulse` did not, for the whole of
 * Skeleton's life, and the à-la-carte path pulsed for reduce users.
 */
@media (prefers-reduced-motion: reduce) {
  .animate-fade-in-up,
  .animate-slide-in-left,
  .animate-scale-in,
  .animate-pulse,
  /* weave-reveal belongs in THIS list, unlike strand-draw below: its
   * keyframe is from-only, so `animation: none` rests at the fully
   * revealed end state — nothing to clamp, nothing hidden. */
  .animate-weave-reveal,
  /* strand-loop rests at the element's own dashoffset, 0: the pair is
   * fully woven and still. */
  .animate-strand-loop {
    animation: none !important;
    transition: none !important;
  }

  /* The draw gesture (MOTION_PHILOSOPHY's draw-gesture exception)
   * completes instantly instead of vanishing: `animation: none` would
   * hold stroke-dashoffset at 100 — the strand invisible forever —
   * removing information, not motion. 0.01ms + the shorthand's
   * `forwards` fill lands the honest drawn end state. */
  .animate-strand-draw {
    animation-duration: 0.01ms !important;
  }
}
} /* end @layer components */

/*
 * @interlace/ui — STRUCTURE / scheme: tell the browser which scheme is on.
 *
 * Layer 3 of 4 (brand → semantics → structure → page). The palette switches
 * on `.dark` / `[data-scheme='dark']`, but the browser's own parts do not
 * read either: scrollbars, form controls, the date picker, autofill and the
 * caret stay light on a dark page unless `color-scheme` says otherwise.
 * Declaring it on the same selectors that switch the palette keeps the two
 * in step, in a subtree too: a `.dark` preview inside a light page gets dark
 * scrollbars, and a `[data-scheme='light']` panel inside a dark page gets
 * light ones. It sits in `@layer base`, so an app's own `color-scheme` wins.
 */

@layer base {
  :root,
  [data-scheme='light'] {
    color-scheme: light;
  }

  .dark,
  [data-scheme='dark'] {
    color-scheme: dark;
  }
}
